//! Phase 8 — ES module emission.
//!
//! Output shape:
//!
//! ```js
//! // Auto-generated by Sail compiler.
//! import { signal, derived, effect, defineComponent, bindText, ... }
//!   from '@sail/runtime'
//!
//! export class MyComponent extends HTMLElement {
//!   static observedAttributes = [...]
//!   connectedCallback() {
//!     // 1. seed prop signals from attributes
//!     // 2. user-script declarations (state/derived/data/effects/functions)
//!     // 3. SSR check + innerHTML if not hydrated
//!     // 4. wire reactive bindings via bind*()
//!     // 5. mount {} block
//!   }
//!   disconnectedCallback() { /* cleanup chain */ }
//!   attributeChangedCallback(name, _, val) { /* sync prop signal */ }
//! }
//! defineComponent('my-component', MyComponent)
//! ```
//!
//! See `02-compiler-architecture.md § Phase 8` for the emit shape and
//! `03-runtime-architecture.md` for the runtime API the emitted code
//! imports.
